/*
 * A085585  Squares with exactly one odd digit.
 * https://oeis.org/A085585
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   not stated
 * Range:     u8 n <= 10, u16 n <= 77, u32 n <= 1607, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* OEIS A085585: Squares with exactly one odd decimal digit, generated by scanning squares sequentially. */

#include <stddef.h>
#include <stdlib.h>

static size_t cache_len = 0;
static size_t cache_cap = 0;
static seq_t *cache = NULL;
static idx_t last_root = 0;   /* last processed square root */

/* append a value to the cache, growing capacity as needed */
static void cache_append(seq_t val) {
    if (cache_len + 1 > cache_cap) {
        size_t new_cap = cache_cap ? cache_cap << 1 : 8;
        seq_t *new_cache = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
        cache = new_cache;
        cache_cap = new_cap;
    }
    cache[cache_len++] = val;
}

/* make sure at least 'n' terms are in the cache */
static void ensure_cache(idx_t n) {
    if (cache_len >= n) return;
    idx_t root = last_root + 1;
    while (cache_len < n) {
        seq_t sq = (seq_t)root * root;

        /* count odd digits */
        seq_t tmp = sq;
        idx_t odd = 0;
        while (tmp != 0) {
            int d = (int)(tmp % 10);
            if (d & 1) {
                ++odd;
                if (odd > 1) break;
            }
            tmp /= 10;
        }
        if (odd == 1) cache_append(sq);

        ++root;
    }
    last_root = root - 1;
}

seq_t a(idx_t n) {
    /* n is guaranteed >= 1 by the problem statement; defensive check */
    if (n == 0) return 0;
    ensure_cache(n);
    return cache[n - 1];
}
